/usr/bin/zsh -lc "node --input-type=module <<'NODE'
import {readFileSync, writeFileSync} from 'node:fs';
const specPath = 'specs/hal-engine-tool-input-validation/spec.md';
let spec = readFileSync(specPath, 'utf8');
for (const file of ['src/orchestration/tools/registry.test.ts', 'src/orchestration/tools/weather-tool.test.ts']) {
  const lines = readFileSync(file, 'utf8').split('\\n');
  const target = "'`../../${file}`;
  spec = spec.replace(/'"\\[validated by: (["'^'"\\]]+)\\]\\((["'^)]+)#L'"\\d+\\)/g, (link, title, path) => {
    if (path "'!== target) return link;
    const index = lines.findIndex(line => line.includes(`it('"'"'${title}'"'"'`));
    if (index < 0) throw new Error(`Missing test: ${title}`);
    return `[validated by: ${title}](${path}#L${index + 1})`;
  });
}
writeFileSync(specPath, spec);
NODE'

